edition = "2023";
package example.v1;
import "google/protobuf/timestamp.proto";
message Request {
  string name = 1;
  map<string, int64> counts = 2;
  oneof result { string text = 3; bytes data = 4; }
  enum Status { UNKNOWN = 0; READY = 1; }
  double ratio = 5 [default = 1.5];
}
service Greeter { rpc Get(Request) returns (stream Request); }
